请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-016

=== 用户原始指令 (query.txt) ===
帮我做个主题色背景的深度专注卡片，用红黑那种紧迫感渐变。里面信息从上到下排：拼一行'今日超时3次'的文字和动态数值，中间用系统警告图标标个红色的告警状态，底下嵌个面板块，里面纵向列三个紧急联系人，一键就能开启系统勿扰模式。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个主题色背景的深度专注卡片，用红黑那种紧迫感渐变。里面信息从上到下排：拼一行'今日超时3次'的文字和动态数值，中间用系统警告图标标个红色的告警状态，底下嵌个面板块，里面纵向列三个紧急联系人，一键就能开启系统勿扰模式。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "focus": {
      "overtimeCount": {
        "type": "number",
        "description": "今日触发专注超时的次数。",
        "sampleValue": 3
      },
      "alertText": {
        "type": "string",
        "description": "当前专注状态的告警提示文本。",
        "sampleValue": "告警"
      }
    },
    "contacts": {
      "contact1": {
        "type": "string",
        "description": "第一位紧急联系人展示名，使用脱敏称谓样例。",
        "sampleValue": "家人"
      },
      "contact2": {
        "type": "string",
        "description": "第二位紧急联系人展示名，使用脱敏称谓样例。",
        "sampleValue": "主管"
      },
      "contact3": {
        "type": "string",
        "description": "第三位紧急联系人展示名，使用脱敏称谓样例。",
        "sampleValue": "伴侣"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "计时图标，适合表达专注超时、防沉迷和告警状态。"
    }
  ]
}

